#!/bin/bash
# dualmut (53 modules): does --preset sound falsely REJECT a valid Mathlib slice whose target was generated by @[to_dual]?
# NFS install (verdict experiment; timings not representative)
T=$(cd "$(dirname "$(readlink -f "$0")")" && pwd)/runml3.sh
NOKTC="toolchain-T1=lean4-7586a50cec-nopgo,linter-off,retries,premise-off,fast-exact,zygote,zygote-prefix,j1-saturated,sound-fast-path,cost-hints,native-pkg,merge,check-tail"
$T dualmut sound 16 -N
$T dualmut reference 16 -N
$T dualmut fast-exact 16 -N
$T dualmut sound 16 -N-noktc --unsafe "$NOKTC"
# official comparator on the sound run's export (the oracle for the export the untrusted build produced)
$T dualmut reference 16 -N-C0-on-sound-export --from-export "${R:-${FV_SCRATCH:-/scratch}/mathlib-as-project}/runs/dualmut.sound-N/solution.export" --check C0
